<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_role('administrador');$pageTitle='Categorías';$errors=[];$current=null;if(isset($_GET['t'])){$id=decode_id($_GET['t']);if(!$id)abort_forbidden('Token alterado.');$s=db()->prepare('SELECT * FROM categorias WHERE id=?');$s->execute([$id]);$current=$s->fetch();}
if(request_is_post()){verify_csrf();$fa=clean_text($_POST['form_action']??'',20);if(in_array($fa,['create','update'],true)){$name=clean_text($_POST['nombre']??'',100);$type=clean_text($_POST['tipo']??'',30);$active=isset($_POST['activo'])?1:0;if(mb_strlen($name)<3)$errors[]='Nombre inválido.';if(!in_array($type,['servicio','portafolio','imagen','contenido'],true))$errors[]='Tipo inválido.';if(!$errors){if($fa==='create'){db()->prepare('INSERT INTO categorias(nombre,slug,tipo,activo)VALUES(?,?,?,?)')->execute([$name,slugify($name).'-'.bin2hex(random_bytes(2)),$type,$active]);flash('success','Categoría creada.');}else{$id=decode_id($_POST['token_id']??'');if(!$id)abort_forbidden('Token alterado.');db()->prepare('UPDATE categorias SET nombre=?,tipo=?,activo=? WHERE id=?')->execute([$name,$type,$active,$id]);flash('success','Categoría actualizada.');}redirect('admin/categorias.php');}}if($fa==='delete'){$id=decode_id($_POST['token_id']??'');if(!$id)abort_forbidden('Token alterado.');db()->prepare('DELETE FROM categorias WHERE id=?')->execute([$id]);flash('success','Categoría eliminada.');redirect('admin/categorias.php');}}
$items=db()->query('SELECT * FROM categorias ORDER BY tipo,nombre')->fetchAll();require dirname(__DIR__).'/includes/admin_header.php';
?>
<div class="panel-heading"><div><h1>Categorías</h1><p>Clasificación de servicios, portafolio, contenido e imágenes.</p></div></div><div class="grid-2"><form class="card" method="post"><?=csrf_field()?><input type="hidden" name="form_action" value="<?=$current?'update':'create'?>"><?php if($current):?><input type="hidden" name="token_id" value="<?=e(encode_id((int)$current['id']))?>"><?php endif;?><h2><?=$current?'Editar categoría':'Nueva categoría'?></h2><?php if($errors):?><div class="error-list"><ul><?php foreach($errors as$er):?><li><?=e($er)?></li><?php endforeach;?></ul></div><?php endif;?><div class="field"><label>Nombre</label><input name="nombre" value="<?=e($current['nombre']??'')?>" required></div><div class="field"><label>Tipo</label><select name="tipo"><?php foreach(['servicio','portafolio','imagen','contenido']as$type):?><option <?=($current['tipo']??'servicio')===$type?'selected':''?>><?=e($type)?></option><?php endforeach;?></select></div><label><input type="checkbox" name="activo" style="width:auto" <?=!$current||$current['activo']?'checked':''?>> Activa</label><div class="actions"><button class="btn">Guardar</button><?php if($current):?><a class="btn btn-light" href="<?=url('admin/categorias.php')?>">Cancelar</a><?php endif;?></div></form><div class="table-card"><div class="table-responsive"><table><thead><tr><th>Nombre</th><th>Tipo</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($items as$it):?><tr><td><?=e($it['nombre'])?></td><td><?=e($it['tipo'])?></td><td><?=$it['activo']?'Activa':'Inactiva'?></td><td class="table-actions"><a class="btn btn-small btn-light" href="<?=url('admin/categorias.php?t='.encode_id((int)$it['id']))?>">Editar</a><form method="post"><?=csrf_field()?><input type="hidden" name="form_action" value="delete"><input type="hidden" name="token_id" value="<?=e(encode_id((int)$it['id']))?>"><button class="btn btn-small btn-danger" data-confirm="¿Eliminar esta categoría?">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div>
<?php require dirname(__DIR__).'/includes/admin_footer.php';?>
